// Package quiclb generates QUIC connection IDs that an AWS Network Load Balancer can route,
// following the unencrypted mode of draft-ietf-quic-load-balancers.
//
// In QUIC passthrough mode, the NLB routes each packet to the target whose server ID is
// embedded in the packet's destination connection ID. The AWS Load Balancer Controller
// injects that server ID into the pods through the AWS_LBC_QUIC_SERVER_ID environment variable.
//
// The NLB drops packets whose connection ID, generated by the target, is not exactly 17 bytes.
// The connection IDs match those of Envoy's QUIC-LB generator, the AWS reference setup:
// a 16-byte QUIC-LB connection ID with a 7-byte nonce, followed by a byte Envoy uses as worker ID,
// which is random here.
//
//	Offset  Length  Field
//	0       1       0x0F: config rotation 0 (3 bits), length of the server ID and nonce minus one (5 bits)
//	1       8       Server ID
//	9       8       Nonce and worker ID (random)
//
// The unencrypted mode exposes the server ID on the wire, which lets an observer link the
// connection IDs of a connection together. The NLB only supports this mode.
package quiclb

import (
	"crypto/rand"
	"encoding/base64"
	"fmt"

	"github.com/quic-go/quic-go"
)

const (
	serverIDLen = 8
	nonceLen    = 8
	cidLen      = 1 + serverIDLen + nonceLen

	// firstByte is what Envoy's QUIC-LB generator writes, with config rotation 0 and a self-encoded length of 15.
	// The NLB does not document the first byte, so this sticks to the setup it is known to route.
	firstByte = 0x0F
)

// Generator is a quic.ConnectionIDGenerator embedding an AWS NLB server ID in every connection ID.
// It is safe for concurrent use.
type Generator struct {
	serverID [serverIDLen]byte
}

// NewGenerator creates a Generator from a base64-encoded server ID.
// It returns a nil Generator and no error when serverIDBase64 is empty.
func NewGenerator(serverIDBase64 string) (*Generator, error) {
	if serverIDBase64 == "" {
		return nil, nil
	}

	decoded, err := base64.StdEncoding.DecodeString(serverIDBase64)
	if err != nil {
		return nil, fmt.Errorf("decoding server ID: %w", err)
	}

	if len(decoded) != serverIDLen {
		return nil, fmt.Errorf("server ID must be %d bytes, got %d", serverIDLen, len(decoded))
	}

	g := &Generator{}
	copy(g.serverID[:], decoded)

	return g, nil
}

// GenerateConnectionID implements quic.ConnectionIDGenerator.
func (g *Generator) GenerateConnectionID() (quic.ConnectionID, error) {
	var buf [cidLen]byte

	// Since Go 1.24, crypto/rand.Read never returns an error.
	_, _ = rand.Read(buf[:])

	buf[0] = firstByte
	copy(buf[1:1+serverIDLen], g.serverID[:])

	return quic.ConnectionIDFromBytes(buf[:]), nil
}

// ConnectionIDLen implements quic.ConnectionIDGenerator.
func (g *Generator) ConnectionIDLen() int {
	return cidLen
}
